-- Carga 36 de 63 de la herramienta arbitros-cr. La arma herramientas/arbitros-cr.py: no se edita a mano.
-- Lee las respuestas del buscador de chess-results que siguen en net._http_response (RESPUESTAS_CR).
with r as (select id, substr(content, strpos(content, '<table class="CRs2"')) t from net._http_response
  where id between 17486 and 17514 and strpos(content, '<table class="CRs2"') > 0),
filas as (select f from r, regexp_split_to_table(substr(t, 1, strpos(t, '</table>')), '<tr class="CR') f where f ~ '^n?g[12]">'),
celdas as (select regexp_split_to_array(f, '</t[dh]>') c from filas),
t as (select distinct on (btrim(regexp_replace(c[19], '<[^>]+>', '', 'g'))::int) btrim(regexp_replace(c[19], '<[^>]+>', '', 'g'))::int clave, c from celdas
  where btrim(regexp_replace(c[19], '<[^>]+>', '', 'g')) ~ '^\d+$')
