  left(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[13], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), 200), left(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[14], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), 200),
